using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ExternalApiTool
{
    [McpServerTool("fetch_resource"), Description("Fetches a resource from the external API by its ID.")]
    public static async Task<string> FetchResourceAsync(
        IHttpClientFactory httpClientFactory,
        ILogger<ExternalApiTool> logger,
        [Description("The unique identifier of the resource to fetch.")] string resourceId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching resource {ResourceId}", resourceId);

        var client = httpClientFactory.CreateClient("ExternalApi");

        var response = await client.GetAsync($"resources/{resourceId}", cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizationPrompt
{
    [McpServerPrompt("summarize"), Description("Summarizes text content at a chosen detail level.")]
    public static IList<McpServerPromptMessage> Summarize(
        [Description("The text content to summarize.")] string content,
        [Description("Detail level: brief, standard, or detailed.")] string style = "standard")
    {
        var systemText = style.ToLowerInvariant() switch
        {
            "brief"    => "You are a summarization assistant. Provide a one-sentence summary.",
            "detailed" => "You are a summarization assistant. Provide a thorough, multi-paragraph summary preserving key details.",
            _          => "You are a summarization assistant. Provide a concise summary in a few sentences.",
        };

        return
        [
            new McpServerPromptMessage
            {
                Role = Role.Assistant,
                Content = new() { Text = systemText, Type = "text" },
            },
            new McpServerPromptMessage
            {
                Role = Role.User,
                Content = new() { Text = $"Summarize the following:\n\n{content}", Type = "text" },
            },
        ];
    }
}

