5. /// <summary>
6. /// Writes log messages to stderr so they never interfere with the
7. /// stdout JSON-RPC transport used by the MCP stdio protocol.
8. /// </summary>
9. internal sealed class StderrLoggerProvider : ILoggerProvider
10. {
11.     public ILogger CreateLogger(string categoryName) => new StderrLogger(categoryName);
12.     public void Dispose() { }
13. 
14.     private sealed class StderrLogger(string category) : ILogger
15.     {
16.         public IDisposable? BeginScope<TState>(TState state) where TState : notnull => null;
17.         public bool IsEnabled(LogLevel logLevel) => logLevel >= LogLevel.Information;
18. 
19.         public void Log<TState>(LogLevel logLevel, EventId eventId, TState state,
20.             Exception? exception, Func<TState, Exception?, string> formatter)
21.         {
22.             if (!IsEnabled(logLevel)) return;
23.             Console.Error.WriteLine($"[{logLevel}] {category}: {formatter(state, exception)}");
